  2260	renderCall(args, theme, context) {
  2261	  const text = (context.lastComponent as Text | undefined) ?? new Text("", 0, 0);
  2262	  let content = theme.fg("toolTitle", theme.bold("my_tool "));
  2263	  content += theme.fg("muted", args.action);
  2264	  if (args.text) {
  2265	    content += " " + theme.fg("dim", `"${args.text}"`);
  2266	  }
  2267	  text.setText(content);
