  2271	
  2272	#### renderResult
  2273	
  2274	Renders the tool result or output:
  2275	
  2276	```typescript
  2277	renderResult(result, { expanded, isPartial }, theme, context) {
  2278	  if (isPartial) {
  2279	    return new Text(theme.fg("warning", "Processing..."), 0, 0);
  2280	  }
  2281	
  2282	  if (result.details?.error) {
  2283	    return new Text(theme.fg("error", `Error: ${result.details.error}`), 0, 0);
  2284	  }
  2285	
  2286	  let text = theme.fg("success", "✓ Done");
  2287	  if (expanded && result.details?.items) {
  2288	    for (const item of result.details.items) {
  2289	      text += "\n  " + theme.fg("dim", item);
  2290	    }
  2291	  }
  2292	  return new Text(text, 0, 0);
  2293	}
